// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, address payer) public {
        amount = bound(amount, 1, type(uint128).max);
        vm.assume(payer != address(0));

        AcceptingReceiver recv = new AcceptingReceiver();

        vm.deal(payer, amount);

        vm.prank(payer);
        (bool sent,) = address(c).call{value: amount}("");
        require(sent, "funding failed");

        bool ok;
        try c.sendMoney(address(recv), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract AcceptingReceiver {
    receive() external payable {}
    fallback() external payable {}
}
